"""Exact rational verification of the path spectral-gap witness."""
from __future__ import annotations
from fractions import Fraction
from typing import Callable, Sequence


def dirichlet_energy(vertices: Sequence[int],
                     weight: Callable[[int, int], Fraction],
                     f: Callable[[int], Fraction]) -> Fraction:
    return sum((weight(x, y) * (f(x) - f(y)) ** 2
                for x in vertices for y in vertices), Fraction(0))


def pairwise_variation(vertices: Sequence[int],
                       f: Callable[[int], Fraction]) -> Fraction:
    return sum(((f(x) - f(y)) ** 2
                for x in vertices for y in vertices), Fraction(0))


def path_weight(x: int, y: int) -> Fraction:
    return Fraction(1) if abs(x - y) == 1 else Fraction(0)


def verify(n: int) -> None:
    V = list(range(n))
    f = lambda x: Fraction(x)
    E = dirichlet_energy(V, path_weight, f)
    Vr = pairwise_variation(V, f)
    assert E == 2 * (n - 1)
    assert Vr == Fraction(n * n * (n * n - 1), 6)
    assert E / Vr == Fraction(12, n * n * (n + 1))
    print(f"n={n:3d}: E={int(E):4d}, Vr={int(Vr):8d}, R(f)={E/Vr}")


if __name__ == "__main__":
    for n in range(2, 13):
        verify(n)
    print("All exact closed forms verified.")

"""Cubic pinching: R(f) trapped in [6 n^-3, 12 n^-3]."""
from __future__ import annotations
from fractions import Fraction
from typing import Sequence


def quotient(n: int) -> Fraction:
    return Fraction(12, n * n * (n + 1))


def window(n: int) -> tuple[Fraction, Fraction]:
    return Fraction(6, n ** 3), Fraction(12, n ** 3)


def report(ns: Sequence[int] = (2, 4, 8, 16, 32, 64, 128, 256)) -> None:
    print(f"{'n':>5} | {'6 n^-3':>12} | {'R(f)':>12} | {'12 n^-3':>12} | {'n^3 R':>9}")
    for n in ns:
        lo, hi = window(n)
        r = quotient(n)
        assert lo <= r <= hi
        print(f"{n:>5} | {float(lo):>12.3e} | {float(r):>12.3e} | "
              f"{float(hi):>12.3e} | {float(n**3 * r):>9.5f}")
    print("n^3 R(f) increases monotonically toward 12.")


if __name__ == "__main__":
    report()

