from __future__ import annotations
from fractions import Fraction
from typing import Tuple


def path_witness(n: int) -> Tuple[Fraction, Fraction, Fraction]:
    E_form = Fraction(2 * (n - 1))
    Vr_form = Fraction(n * n * (n * n - 1), 6)
    R_form = Fraction(12, n * n * (n + 1))
    E = Fraction(0)
    Vr = Fraction(0)
    for x in range(n):
        for y in range(n):
            d = Fraction((x - y) ** 2)
            Vr += d
            if abs(x - y) == 1:
                E += d
    assert E == E_form and Vr == Vr_form and E / Vr == R_form
    return E_form, Vr_form, R_form


if __name__ == '__main__':
    for n in range(2, 13):
        print(n, path_witness(n))
